const VALID_PILLARS  = ['interview-prep','career-growth','job-search','ai-tools','product-updates','behavioral','technical','salary'];
const VALID_ANGLES   = ['cv-jd-context','mock-interview','real-time-coaching','interview-conversion'];
const VALID_PERSONAS = ['software_engineer','fresh_graduate','career_shifter','non_tech_professional'];
const VALID_TONES    = ['clear_practical','direct_supportive','concise_confident'];
const ALLOWED_KEYS   = new Set(['request_id','topic','content_pillar','product_angle','target_persona','tone','requested_by']);

const body = $input.first().json.body;
const errors = [];

// Unknown key check
for (const key of Object.keys(body)) {
  if (!ALLOWED_KEYS.has(key)) errors.push('unknown_key: ' + key);
}

// request_id
const rid = (body.request_id ?? '').toString().trim();
if (!rid) errors.push('request_id: required');

// topic
const topic = (body.topic ?? '').toString().trim();
if (!topic) errors.push('topic: required');
else if (topic.length < 10 || topic.length > 120) errors.push('topic: must be 10-120 chars, got ' + topic.length);

// content_pillar
const pillar = (body.content_pillar ?? '').toString();
if (!pillar) errors.push('content_pillar: required');
else if (!VALID_PILLARS.includes(pillar)) errors.push('content_pillar: invalid value "' + pillar + '"');

// product_angle
const angle = (body.product_angle ?? '').toString();
if (!angle) errors.push('product_angle: required');
else if (!VALID_ANGLES.includes(angle)) errors.push('product_angle: invalid value "' + angle + '"');

// target_persona
const persona = (body.target_persona ?? '').toString();
if (!persona) errors.push('target_persona: required');
else if (!VALID_PERSONAS.includes(persona)) errors.push('target_persona: invalid value "' + persona + '"');

// tone
const tone = (body.tone ?? '').toString();
if (!tone) errors.push('tone: required');
else if (!VALID_TONES.includes(tone)) errors.push('tone: invalid value "' + tone + '"');

// requested_by
const requestedBy = (body.requested_by ?? '').toString().trim();
if (!requestedBy) errors.push('requested_by: required');
else if (requestedBy.length > 50) errors.push('requested_by: max 50 chars');

if (errors.length > 0) throw new Error('input_invalid: ' + errors.join('; '));

return [{ json: { valid: true, body, requestId: rid } }];

const payload = JSON.stringify($input.first().json.blogPayload);

// Finalized inline configuration (n8n free-plan friendly).
const INLINE_SECRET = 'REPLACE_WITH_DIWA_BLOG_WEBHOOK_SECRET';
const INLINE_URL = 'https://app.diwacopilot.com/api/webhooks/blog';

const secret = String(INLINE_SECRET || '').trim();
const url = String(INLINE_URL || '').trim();

if (!secret || secret === 'REPLACE_WITH_DIWA_BLOG_WEBHOOK_SECRET') {
  throw new Error('downstream_config: replace INLINE_SECRET with your actual webhook secret');
}
if (secret.includes('%')) {
  throw new Error('downstream_config: INLINE_SECRET contains invalid "%" character (often from copy/paste)');
}
if (/\s/.test(secret)) {
  throw new Error('downstream_config: INLINE_SECRET contains whitespace/newline characters');
}
if (!url) throw new Error('downstream_config: INLINE_URL not configured');
if (!this.helpers?.httpRequest) throw new Error('downstream_runtime: n8n httpRequest helper not available');

function toByteString(input) {
  return unescape(encodeURIComponent(input));
}

function hexToByteString(hex) {
  let out = '';
  for (let i = 0; i < hex.length; i += 2) {
    out += String.fromCharCode(parseInt(hex.slice(i, i + 2), 16));
  }
  return out;
}

function sha256Hex(byteStr) {
  const rightRotate = (value, amount) => (value >>> amount) | (value << (32 - amount));
  const mathPow = Math.pow;
  const maxWord = mathPow(2, 32);
  const lengthProperty = 'length';
  let i;
  let j;
  let result = '';

  const words = [];
  const asciiBitLength = byteStr[lengthProperty] * 8;

  const hash = [
    1779033703,
    -1150833019,
    1013904242,
    -1521486534,
    1359893119,
    -1694144372,
    528734635,
    1541459225,
  ];
  const k = sha256Hex.k || [];
  let primeCounter = k[lengthProperty];

  const isComposite = {};
  for (let candidate = 2; primeCounter < 64; candidate++) {
    if (!isComposite[candidate]) {
      for (i = 0; i < 313; i += candidate) {
        isComposite[i] = candidate;
      }
      k[primeCounter++] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
    }
  }

  sha256Hex.k = k;

  byteStr += '\x80';
  while ((byteStr[lengthProperty] % 64) - 56) byteStr += '\x00';
  for (i = 0; i < byteStr[lengthProperty]; i++) {
    j = byteStr.charCodeAt(i);
    words[i >> 2] |= j << (((3 - i) % 4) * 8);
  }
  words[words[lengthProperty]] = (asciiBitLength / maxWord) | 0;
  words[words[lengthProperty]] = asciiBitLength;

  for (j = 0; j < words[lengthProperty]; ) {
    const w = words.slice(j, (j += 16));
    const oldHash = hash.slice(0);

    for (i = 0; i < 64; i++) {
      const w15 = w[i - 15];
      const w2 = w[i - 2];

      const a = hash[0];
      const e = hash[4];
      const temp1 =
        hash[7] +
        (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25)) +
        ((e & hash[5]) ^ (~e & hash[6])) +
        k[i] +
        (w[i] =
          i < 16
            ? w[i]
            : (w[i - 16] +
                (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3)) +
                w[i - 7] +
                (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))) |
              0);
      const temp2 =
        (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22)) +
        ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));

      hash.unshift((temp1 + temp2) | 0);
      hash[4] = (hash[4] + temp1) | 0;
      hash.pop();
    }

    for (i = 0; i < 8; i++) {
      hash[i] = (hash[i] + oldHash[i]) | 0;
    }
  }

  for (i = 0; i < 8; i++) {
    for (j = 3; j + 1; j--) {
      const b = (hash[i] >> (j * 8)) & 255;
      result += ((b < 16) ? '0' : '') + b.toString(16);
    }
  }
  return result;
}

function hmacSha256Hex(key, message) {
  const blockSize = 64;
  let keyBytes = toByteString(key);

  if (keyBytes.length > blockSize) {
    keyBytes = hexToByteString(sha256Hex(keyBytes));
  }

  while (keyBytes.length < blockSize) keyBytes += '\x00';

  let oKeyPad = '';
  let iKeyPad = '';
  for (let i = 0; i < blockSize; i++) {
    const c = keyBytes.charCodeAt(i);
    oKeyPad += String.fromCharCode(c ^ 0x5c);
    iKeyPad += String.fromCharCode(c ^ 0x36);
  }

  const msgBytes = toByteString(message);
  const innerHashHex = sha256Hex(iKeyPad + msgBytes);
  const innerHashBytes = hexToByteString(innerHashHex);
  return sha256Hex(oKeyPad + innerHashBytes);
}

async function attempt(retryDelays) {
  for (let i = 0; i <= retryDelays.length; i++) {
    if (i > 0) await new Promise(r => setTimeout(r, retryDelays[i - 1]));

    const ts = Date.now().toString();
    const sig = hmacSha256Hex(secret, ts + '.' + payload);

    let res;
    try {
      res = await this.helpers.httpRequest({
        method: 'POST',
        url,
        json: false,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
        timeout: 30000,
        headers: {
          'Content-Type': 'application/json',
          'X-Webhook-Signature': 'sha256=' + sig,
          'X-Webhook-Timestamp': ts,
        },
        body: payload,
      });
    } catch (err) {
      if (i === retryDelays.length) throw new Error('downstream_5xx_retry_exhausted: network error after retries: ' + err.message);
      continue;
    }

    const status = res.statusCode ?? 0;
    const rawBody = res.body;

    if (status === 201) {
      let resBody;
      if (typeof rawBody === 'object' && rawBody !== null) {
        resBody = rawBody;
      } else {
        try { resBody = JSON.parse(String(rawBody || '{}')); } catch { resBody = {}; }
      }
      return { status, body: resBody };
    }

    if (status === 409) {
      let errBody;
      if (typeof rawBody === 'object' && rawBody !== null) {
        errBody = rawBody;
      } else {
        try { errBody = JSON.parse(String(rawBody || '{}')); } catch { errBody = {}; }
      }
      throw new Error('downstream_conflict_409: slug already exists: ' + JSON.stringify(errBody));
    }

    if (status >= 400 && status < 500) {
      let errBody;
      if (typeof rawBody === 'object' && rawBody !== null) {
        errBody = rawBody;
      } else {
        try { errBody = JSON.parse(String(rawBody || '{}')); } catch { errBody = {}; }
      }
      throw new Error('downstream_4xx: status ' + status + ': ' + JSON.stringify(errBody));
    }

    if (i === retryDelays.length) {
      throw new Error('downstream_5xx_retry_exhausted: status ' + status + ' after ' + (i + 1) + ' attempts');
    }
  }
}

const result = await attempt([5000, 15000, 30000]);
return [{ json: { deliveryStatus: result.status, deliveryBody: result.body } }];

function esc(v) {
  if (typeof v !== 'string') return v;
  return /^[=+\-@]/.test(v) ? "'" + v : v;
}
