const data = $("Get row(s) in sheet").first().json;
const TONES = ['clear_practical','direct_supportive','concise_confident'];

const cache = $getWorkflowStaticData('global');
const lastToneIdx = typeof cache.lastToneIdx    === 'number' ? cache.lastToneIdx    : -1;
const toneIdx = (lastToneIdx + 1) % TONES.length;

cache.lastToneIdx    = toneIdx;

const body = {
  request_id: data.row_number,
  topic: data.topic,
  content_pillar: data.content_pillar,
  product_angle: data.suggested_angle,
  target_persona: data.suggested_persona,
  tone:           TONES[toneIdx],
  requested_by:   'scheduler',
};

return [{ json: { valid: true, body, requestId: body.request_id } }];
